insert into heritage_assets (entity_id,parent_entity_id,asset_type,description,date_from_text,is_current,materials,historical_context,display_order,is_featured) select a.id,h.id,'Orfebrería','Coronas de plata labrada a fuego con adornos de pedrería para la Virgen y el Niño.','Finales del siglo XVI',true,'Plata y pedrería','Piezas históricas asociadas al conjunto iconográfico de Nuestra Señora de los Reyes.',1,true from entities a,entities h where a.slug='coronas-reyes-sastres' and h.slug='reyes-sastres-sevilla' on conflict (entity_id) do update set description=excluded.description,date_from_text=excluded.date_from_text,is_current=true,materials=excluded.materials,historical_context=excluded.historical_context;
