insert into heritage_assets (entity_id,parent_entity_id,asset_type,description,date_from_text,is_current,technique,historical_context,display_order,is_featured) select a.id,h.id,'Bordado','Techo de tumbilla del paso procesional, completamente bordado tras culminar en 2024 el proceso diseñado y ejecutado por Manuel Ojeda Rodríguez.','Culminado en 2024',true,'Bordado','Estreno patrimonial culminado en la procesión del 28 de septiembre de 2024.',2,true from entities a,entities h where a.slug='techo-tumbilla-reyes-sastres' and h.slug='reyes-sastres-sevilla' on conflict (entity_id) do update set description=excluded.description,date_from_text=excluded.date_from_text,is_current=true,technique=excluded.technique,historical_context=excluded.historical_context;
