insert into events (entity_id,event_type,event_date_text,description,event_category,brotherhood_entity_id,municipality_id,event_status,public_notes) select ev.id,'Hito histórico','1252','La parroquia documenta noticia fehaciente de la existencia de la corporación en 1252, diferenciándola de la tradición que sitúa sus orígenes durante el cerco de Sevilla.','historical',h.id,m.id,'held','Se conserva la distinción entre tradición de origen y evidencia documental.' from entities ev,entities h,municipalities m where ev.slug='sastres-constancia-documental-1252' and h.slug='reyes-sastres-sevilla' and m.slug='sevilla' on conflict (entity_id) do update set event_date_text=excluded.event_date_text,description=excluded.description,brotherhood_entity_id=excluded.brotherhood_entity_id,municipality_id=excluded.municipality_id,event_status='held';
insert into entities (entity_type,name,slug,summary,status) select 'event','Traslado de la Hermandad de los Sastres a San Ildefonso','sastres-san-ildefonso-1840','La Hermandad pasó a la iglesia de San Ildefonso en 1840 tras abandonar el Convento Casa Grande de San Francisco.','published' where not exists (select 1 from entities where slug='sastres-san-ildefonso-1840');
