-- Hilo Cofrade · cierre documental de Nuestra Señora de los Reyes · Sastres
-- Corte: 2026-09-05
-- Solo DML editorial. Sin DDL, RLS ni cambios estructurales.

-- Identidad y sede
select m.id,'Parroquia de San Ildefonso y Santiago','parroquia-san-ildefonso-santiago-sevilla','Parroquia','Plaza de San Ildefonso, Sevilla','Sede canónica de la Hermandad de los Sastres desde 1840.'
from municipalities m where m.slug='sevilla'
and not exists (select 1 from places where slug='parroquia-san-ildefonso-santiago-sevilla');

update brotherhoods set
 official_name='Primitiva, Real, Muy Antigua y Fervorosa Hermandad de Nuestra Señora de los Reyes, Patrona de los Sastres, San Mateo Apóstol y Evangelista y San Fernando Rey',
 popular_name='Hermandad de los Sastres',
 foundation_text='Existencia documentada en 1252; la tradición corporativa remonta sus orígenes al cerco y conquista de Sevilla por San Fernando.',
 municipality_id=(select id from municipalities where slug='sevilla'),
 canonical_see_place_id=(select id from places where slug='parroquia-san-ildefonso-santiago-sevilla'),
 neighborhood='Centro · San Ildefonso',
 current_procession_day='Último sábado de septiembre',
 history_text='La Hermandad de Nuestra Señora de los Reyes, conocida popularmente como de los Sastres por su histórica vinculación al gremio de maestros sastres o alfayates, conserva noticia fehaciente de su existencia en 1252. Sus orígenes tradicionales se sitúan en tiempos de San Fernando. A comienzos del siglo XVII se estableció en el Convento Casa Grande de San Francisco y, tras la demolición de aquel conjunto, pasó en 1840 a la iglesia de San Ildefonso, su sede actual. La procesión anual de septiembre fue recuperada en 2003 tras un prolongado periodo sin celebrarse.'
where entity_id=(select id from entities where slug='reyes-sastres-sevilla');

update entities set name='Nuestra Señora de los Reyes · Sastres',summary='Primitiva corporación letífica sevillana vinculada históricamente al gremio de sastres. Documentada desde 1252, tiene su sede en San Ildefonso desde 1840 y celebra la procesión de Nuestra Señora de los Reyes el último sábado de septiembre.',updated_at=now() where slug='reyes-sastres-sevilla';

-- Titular
select 'image','Nuestra Señora de los Reyes, Patrona de los Sastres','nuestra-senora-reyes-sastres-imagen','Imagen mariana sedente y de vestir, de autor desconocido y fechada en el siglo XVI, que reproduce el tipo iconográfico de la Patrona de Sevilla.','published'
where not exists (select 1 from entities where slug='nuestra-senora-reyes-sastres-imagen');
select id,'Virgen','Siglo XVI','Madera policromada','Imagen sedente de Nuestra Señora de los Reyes, Patrona de los Sastres, de autor desconocido. El Niño Jesús es una imagen barroca posterior, igualmente de autor no documentado.','Virgen sedente como Reina y Trono del Divino Infante',true,'La intervención de 2005 de Almudena Fernández García y José Joaquín Fijo León recuperó una policromía dieciochesca subyacente.' from entities where slug='nuestra-senora-reyes-sastres-imagen'
on conflict (entity_id) do update set execution_date_text=excluded.execution_date_text,description=excluded.description,iconography=excluded.iconography,is_dress_image=excluded.is_dress_image,notes=excluded.notes;
select h.id,i.id,'Titular','Titular mariana y Patrona de los Sastres.','published' from entities h,entities i where h.slug='reyes-sastres-sevilla' and i.slug='nuestra-senora-reyes-sastres-imagen'
and not exists (select 1 from brotherhood_images x where x.brotherhood_entity_id=h.id and x.image_entity_id=i.id and x.relation_type='Titular');

-- Paso
select 'step','Paso de tumbilla de Nuestra Señora de los Reyes','paso-tumbilla-reyes-sastres','Paso procesional de tumbilla de Nuestra Señora de los Reyes, inspirado en la disposición tradicional de la Patrona de Sevilla.','published'
where not exists (select 1 from entities where slug='paso-tumbilla-reyes-sastres');
select id,'Gloria','preserved','Paso de tumbilla sobre el que procesiona Nuestra Señora de los Reyes. Su techo de tumbilla culminó en 2024 un proceso de bordado diseñado y ejecutado por Manuel Ojeda Rodríguez.','Tumbilla','Configuración vigente documentada en las procesiones de 2024 y 2025.' from entities where slug='paso-tumbilla-reyes-sastres'
on conflict (entity_id) do update set current_condition=excluded.current_condition,description=excluded.description,style=excluded.style,current_state_notes=excluded.current_state_notes;
select h.id,s.id,'Paso actual','Paso procesional de la Virgen en la procesión anual de septiembre.','published' from entities h,entities s where h.slug='reyes-sastres-sevilla' and s.slug='paso-tumbilla-reyes-sastres'
and not exists (select 1 from brotherhood_steps x where x.brotherhood_entity_id=h.id and x.step_entity_id=s.id and x.relation_type='Paso actual');
select i.id,s.id,'Procesiona en','Nuestra Señora de los Reyes procesiona en este paso de tumbilla.','published' from entities i,entities s where i.slug='nuestra-senora-reyes-sastres-imagen' and s.slug='paso-tumbilla-reyes-sastres'
and not exists (select 1 from image_steps x where x.image_entity_id=i.id and x.step_entity_id=s.id and x.relation_type='Procesiona en');

-- Cultos recurrentes; no se inventan fechas exactas de septiembre de 2026
select h.id,i.id,'Festividad','Festividad de Nuestra Señora de los Reyes','15 de agosto',8,'Culto en torno a la festividad litúrgica de Nuestra Señora de los Reyes; en 2026 la imagen fue expuesta a la veneración de los fieles en la víspera.','published',true,'Cada 15 de agosto',1,'La forma concreta del culto se determina en la convocatoria anual.' from entities h,entities i where h.slug='reyes-sastres-sevilla' and i.slug='nuestra-senora-reyes-sastres-imagen' and not exists (select 1 from cults c where c.brotherhood_entity_id=h.id and c.title='Festividad de Nuestra Señora de los Reyes');
select h.id,i.id,'Triduo','Solemne Triduo a Nuestra Señora de los Reyes','Fechas según convocatoria anual',9,'Triduo solemne en honor de la titular. En 2024 y 2025 se celebró en septiembre, sin trasladar automáticamente esas fechas a 2026.','published',true,'Anual',2,'No existe aún una ocurrencia exacta de septiembre de 2026.' from entities h,entities i where h.slug='reyes-sastres-sevilla' and i.slug='nuestra-senora-reyes-sastres-imagen' and not exists (select 1 from cults c where c.brotherhood_entity_id=h.id and c.title='Solemne Triduo a Nuestra Señora de los Reyes');
select h.id,i.id,'Función','Función Principal de Instituto','Según convocatoria anual',9,'Función Principal de Instituto de la corporación, ligada en la práctica reciente al ciclo de cultos de septiembre.','published',true,'Anual',3,'La tradición histórica la vinculó también a fechas próximas al 23 de noviembre; no se fija una regla inmutable ante la variación contemporánea.' from entities h,entities i where h.slug='reyes-sastres-sevilla' and i.slug='nuestra-senora-reyes-sastres-imagen' and not exists (select 1 from cults c where c.brotherhood_entity_id=h.id and c.title='Función Principal de Instituto');

-- Salidas
select h.id,'Gloria','ordinary','Procesión anual de Nuestra Señora de los Reyes',date '2025-09-27',2025,m.id,p.id,p.id,'Procesión anual del último sábado de septiembre','Procesión gloriosa desde San Ildefonso con estaciones en el entorno de San Leandro, Santiago y San Esteban.','held','published','San Ildefonso · Cristo de Burgos · San Leandro · Santiago · San Esteban · San Ildefonso','Última procesión anual con fecha exacta documentada en esta carga. La salida de 2026 no se anticipa hasta convocatoria propia.','Parroquia de San Ildefonso y Santiago','Parroquia de San Ildefonso y Santiago' from entities h,municipalities m,places p where h.slug='reyes-sastres-sevilla' and m.slug='sevilla' and p.slug='parroquia-san-ildefonso-santiago-sevilla' and not exists (select 1 from outings o where o.brotherhood_entity_id=h.id and o.outing_date=date '2025-09-27' and o.title='Procesión anual de Nuestra Señora de los Reyes');
select h.id,'Extraordinaria','extraordinary','Participación en el Congreso Mariano Nacional de Zaragoza',1954,m.id,'Congreso Mariano Nacional y consagración al Inmaculado Corazón de María','Nuestra Señora de los Reyes de los Sastres fue trasladada a Zaragoza y participó en la procesión mariana del Congreso de 1954.','held','published','Acontecimiento histórico; no debe aparecer como salida futura o anunciada.','Sevilla','Zaragoza' from entities h,municipalities m where h.slug='reyes-sastres-sevilla' and m.slug='sevilla' and not exists (select 1 from outings o where o.brotherhood_entity_id=h.id and o.year=1954 and o.title='Participación en el Congreso Mariano Nacional de Zaragoza');

-- Música: última continuidad documentada, sin marcar 2026 como actual
select h.id,b.id,s.id,'Tras la Virgen','Gloria',2024,2025,false,'Acompañamiento documentado en las procesiones de 2024 y 2025. No se presenta como vigente para 2026 mientras no exista confirmación específica de la próxima salida.','published','Nuestra Señora de los Reyes · Sastres','Paso de tumbilla de Nuestra Señora de los Reyes','reyes-sastres-sevilla','Sevilla','sevilla','Sevilla' from entities h,entities b,entities s where h.slug='reyes-sastres-sevilla' and b.slug='las-cigarreras' and s.slug='paso-tumbilla-reyes-sastres' and not exists (select 1 from music_accompaniment_periods x where x.brotherhood_entity_id=h.id and x.band_entity_id=b.id and x.year_from=2024 and x.year_to=2025);

